/*
 * test_sine.cpp — Minimal xpatch.cpp equivalent for testing the shim layer
 *
 * This file mimics the structure of a real xpatch.cpp generated by the
 * Akso/Ksoloti patcher, but contains only a simple sine oscillator.
 * If this compiles and links against the shim headers, the shim works.
 */

#include "axoloti_compat.h"

/* ---- Root patch class (matches generated structure) ---- */

class rootc {
public:
    static const uint32_t nparams = 1;
    ParameterExchange_t PExch[nparams];
    Parameter_name_t param_names[nparams];

    static const uint32_t NPRESETS = 0;
    static const uint32_t NPRESET_ENTRIES = 0;

    static const uint32_t ndisplay_metas = 0;
    int32_t displayVector[1];
    Display_meta_t display_metas[1];

    int32buffer AudioInputLeft;
    int32buffer AudioInputRight;
    int32buffer AudioOutputLeft;
    int32buffer AudioOutputRight;

    /* Sine oscillator state */
    uint32_t phase;
    uint32_t freq;

    void Init() {
        phase = 0;
        /* Default frequency: A4 (440 Hz) as Q31 phase increment
         * 440/48000 * 2^32 ≈ 39370534 */
        freq = 39370534;

        /* Set up parameter for pitch control */
        PExch[0].value = 0;
        PExch[0].modvalue = 0;
        PExch[0].finalvalue = 0;
        PExch[0].pfunction = pfun_signed_clamp;
        PExch[0].signals = 0;
        memcpy(param_names[0].name, "pitch\0\0\0", 8);

        /* Register metadata */
        patchMeta.numPEx = nparams;
        patchMeta.pPExch = PExch;
        patchMeta.pDisplayVector = displayVector;
        patchMeta.npresets = NPRESETS;
        patchMeta.npreset_entries = NPRESET_ENTRIES;
        patchMeta.pPresets = nullptr;
    }

    void dsp() {
        int i;
        /* Compute frequency from pitch parameter */
        int32_t pitch = PExch[0].finalvalue;
        MTOF(pitch, freq);

        /* Generate sine wave */
        for (i = 0; i < BUFSIZE; i++) {
            int32_t out;
            SINE2TINTERP(phase, out);
            phase += freq;
            /* Scale output to ~50% to avoid clipping */
            AudioOutputLeft[i] = out >> 5;
            AudioOutputRight[i] = out >> 5;
        }
    }

    void Dispose() {}

    void MidiInHandler(midi_device_t dev, uint8_t port,
                       uint8_t status, uint8_t data1, uint8_t data2) {
        /* Handle note on: set pitch from MIDI note number */
        if ((status & 0xF0) == MIDI_NOTE_ON && data2 > 0) {
            PExParameterChange(&PExch[0], (data1 - 64) << 21, 0xFFFFFFFF);
        }
    }

    void ApplyPreset(int index) {
        (void)index;
    }
};

/* ---- Static root instance ---- */
static rootc root;

/* ---- Entry points (matching xpatch.cpp conventions) ---- */

void PatchProcess(int32_t *inbuf, int32_t *outbuf) {
    int i;
    for (i = 0; i < BUFSIZE; i++) {
        root.AudioInputLeft[i] = inbuf[i * 2] >> 4;
        root.AudioInputRight[i] = inbuf[i * 2 + 1] >> 4;
    }

    root.dsp();

    for (i = 0; i < BUFSIZE; i++) {
        outbuf[i * 2] = __SSAT(root.AudioOutputLeft[i], 28) << 4;
        outbuf[i * 2 + 1] = __SSAT(root.AudioOutputRight[i], 28) << 4;
    }
}

extern "C" __attribute__((section(".boot")))
void xpatch_init(int32_t fwid) {
    (void)fwid;
    root.Init();
}

void PatchMidiInHandler(midi_device_t dev, uint8_t port,
                         uint8_t status, uint8_t data1, uint8_t data2) {
    root.MidiInHandler(dev, port, status, data1, data2);
}

void ApplyPreset(int32_t i) {
    root.ApplyPreset(i);
}

void PatchDispose(void) {
    root.Dispose();
}
